(* [comment removed for export] *)
Lemma eqnm_b1 : forall lc, 0 <= lc < 2^64 -> lc <> 1 ->
  bv_eqb (v_sltiu (Z_to_bv 64 (lc + -1)) 1) (v_sltiu (Z_to_bv 64 2) 1) = true.
Proof.
  intros lc H H1. rewrite !v_sltiu_b2z, bv_eqb_Z. change (bv_wrap 64 1) with 1.
  rewrite (unsigned_lit 2) by lia.
  replace (bv_unsigned (Z_to_bv 64 (lc + -1)) <? 1) with false.
  2:{ symmetry. apply Z.ltb_ge. destruct (Z.eq_dec lc 0) as [->|].
      - rewrite unsigned_lit_wrap. change ((0 + -1) mod 2 ^ 64) with (2^64 - 1). lia.
      - rewrite unsigned_lit by lia. lia. }
  reflexivity.
Qed.

Lemma zx32_wz : forall x, 0 <= x < 2^32 -> zx32 (wz x) = wz x.
Proof. intros x Hx. unfold zx32, wz. rewrite unsigned_lit by lia. rewrite Z.mod_small by lia. reflexivity. Qed.

(* [comment removed for export] *)
Lemma wrap_nullbase_xor_pos : forall b s, 0 < b -> 0 < s -> Z.lxor (Z.b2z (0 <? b)) (Z.b2z (s <? 1)) = 1.
Proof.
  intros b s Hb Hs. destruct (Z.ltb_spec 0 b); destruct (Z.ltb_spec s 1); cbn; first [reflexivity | exfalso; lia].
Qed.

(* [comment removed for export] *)
Local Ltac seg2_script RET LOC pc_ld DONE :=
  intros rv rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
         F fc m P IN E lo c pad7 pad2 j8 junk p0 in1 n E1 g;
  intros FRM PC PCOK IT EC EOK EHC HC XS ST LO IMG PLO PHI ILO IHI ELO EHI DPI DPE DIE IN1 P0 IN1H NR MI;
  let TMPe := fresh "TMPe" in let TMPf := fresh "TMPf" in let HCo := fresh "HCo" in let HCg := fresh "HCg" in
  let ECAT := fresh "ECAT" in let EFL := fresh "EFL" in let XSf := fresh "XSf" in let EV31 := fresh "EV31" in
  pose proof PCOK as PCOK'; pose proof EOK as EOK';
  destruct FRM as (FR0 & TMP & FRhi);
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof (munch_refl (seg2_W lo sp P E) m) as MU; pose proof (wmono_refl usegs m) as WM;
  destruct PCOK as (Bh & Bl & Ln & Ln0 & Sk & Hl & Stt & Ff);
  unfold seg2_W, RET, G_HTTP_CAT in *; unfold ErrCodeCells in EC; unfold ParserCoreCells in PC; unfold wz in *;
  cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  (* [comment removed for export] *)
  step; step; step; step;
  call_assignA_with (bv_unsigned sp + -80) (bv_unsigned sp + -72) 3 lo g junk;
  clear HC XS;
  lazymatch goal with TMP' : rw_cells _ _ (bv_unsigned sp + -72) (ErrCodeCells _) |- _ => rename TMP' into TMPe end;
  destruct EOK as (EV & ECt & EF & EF1);
  assert (EV31 : 0 <= ec_val E1 < 2^31) by (destruct EHC as [-> | (_ & _ & ?)]; [cbn; lia | assumption]);
  (* [comment removed for export] *)
  step; step; step;
  lazymatch goal with HC' : HttpCat _ true |- _ =>
    destruct HC' as [HCo HCg]; cbn [HttpCatCells HttpCatGuardCells] in HCo, HCg; unfold G_HTTP_CAT, G_HTTP_CAT_GUARD in HCo, HCg end;
  let ES := fresh "ES" in
  pose proof eceq_spec as ES; unfold eceq_stmt, eceq_post, P_UB_EC_EQ, ErrCodeCells in ES; unfold wz in ES;
  call (ES E (bv_unsigned sp + -72) 0x95050 VP_HTTP_ECAT HTTP_CAT_ID E1 (EC_http 3) [CB 40 (zeros 40)]);
  [ exact EC | exact EOK' | exact EV31 | exact TMPe
  | unfold ec_ok, EC_http, ec_make, G_HTTP_CAT; cbn; lia | cbn; lia | cbn; lia | reflexivity
  | let HV := fresh "HV" in intros HV; destruct EHC as [EE | (CA & FL & _)]; [exfalso; rewrite EE in HV; cbn in HV; lia | split; [exact CA | exact FL]]
  | exact HCo | unfold HTTP_CAT_ID; lia | lia | reflexivity | rewrite unsigned_lit by lia; reflexivity | assumption | ];
  subst; clear ES;
  let HCb := fresh "HCb" in
  assert (HCb : HttpCat _ true) by (split; [exact HCo | exact HCg]); clear HCo HCg;
  unfold eceq_res; cbn [ec_val EC_http ec_make];
  let V3 := fresh "V3" in
  destruct (Z.eqb_spec (ec_val E1) 3) as [V3|V3];
  [ (* [comment removed for export] *)
    step; if_false;
    destruct EHC as [EE | (ECAT & EFL & _)]; [exfalso; rewrite EE in V3; cbn in V3; lia|];
    (* [comment removed for export] *)
    step; change (zx32 (Z_to_bv 64 (pc_hlim c))) with (zx32 (wz (pc_hlim c))); rewrite zx32_wz by lia; unfold wz;
    let KH := fresh "KH" in
    step; if_cases KH; zify_cond KH; rewrite ?unsigned_lit in KH by lia;
    [ (* [comment removed for export] *)
      unfold seg2_post; replace (psl_ec E1 n (pc_hlim c) LOC) with E1
        by (unfold psl_ec; replace (pc_hlim c <=? n) with false by (symmetry; apply Z.leb_gt; lia); rewrite Bool.andb_false_r; reflexivity);
      eapply DONE; try eassumption; try lia; split; [exact FR0 | split; [exact TMPe | exact FRhi]]
    | (* [comment removed for export] *)
      let junk2 := fresh "junk2" in let TMP2 := fresh "TMP2" in
      destruct (rw_cells_forget _ _ _ _ TMPe) as [junk2 TMP2]; cbn [cells_size csize Nat.add] in TMP2; clear TMPe;
      step; step; step; step;
      call_assignA_with (bv_unsigned sp + -80) (bv_unsigned sp + -72) 8 lo true junk2;
      clear HCb;
      lazymatch goal with TMP' : rw_cells _ _ (bv_unsigned sp + -72) (ErrCodeCells _), HC' : HttpCat _ true, XS' : XStatics _ |- _ =>
        concretize_ec TMP'; rename TMP' into TMPf;
        (* [comment removed for export] *)
        steps_to pc_ld;
        expose_statics HC' XS' [(E, E + 24)]%Z;
        (* [comment removed for export] *)
        step; step; st1; st1; st1
      end;
      unfold seg2_post; replace (psl_ec E1 n (pc_hlim c) LOC) with (EC_http_loc HE_HEADER_LIMIT LOC)
        by (unfold psl_ec, is_needmore, HE_NEED_MORE; rewrite ECAT, V3; unfold G_HTTP_CAT; cbn [Z.eqb Pos.eqb andb];
            replace (2 <=? ec_flags E1) with true by (symmetry; apply Z.leb_le; lia);
            replace (pc_hlim c <=? n) with true by (symmetry; apply Z.leb_le; lia); reflexivity);
      lazymatch goal with XS' : XStatics ?mx, MU2 : munch [(E, E + 24)]%Z ?mx _, WM2 : wmono _ ?mx _ |- _ =>
        pose proof (XStatics_transport _ _ _ XS' MU2 WM2 ltac:(repeat constructor; cbn; lia)) as XSf
      end;
      eapply DONE; try eassumption; try lia; [ split; [exact FR0 | split; [exact TMPf | exact FRhi]] | split; assumption ] ]
  | (* [comment removed for export] *)
    step; if_true;
    unfold seg2_post; replace (psl_ec E1 n (pc_hlim c) LOC) with E1
      by (unfold psl_ec, is_needmore, HE_NEED_MORE; replace (ec_val E1 =? 3) with false by (symmetry; apply Z.eqb_neq; exact V3);
          rewrite Bool.andb_false_r; reflexivity);
    eapply DONE; try eassumption; try lia; split; [exact FR0 | split; [exact TMPe | exact FRhi]] ].
Scheme kc__2 := Elimination for Corelib.Init.Logic.ex Sort Prop.
Scheme kc__3 := Elimination for Corelib.Init.Logic.or Sort Prop.
